from collections import deque

def bus_routes(routes, source, target):
    """
    Find minimum number of buses to travel from source to target stop.
    Returns -1 if impossible.
    """
    if source == target:
        return 0

    # Build adjacency list: stop -> list of route indices
    bus_stops = {}
    for i, route in enumerate(routes):
        for stop in route:
            if stop not in bus_stops:
                bus_stops[stop] = []
            bus_stops[stop].append(i)

    if source not in bus_stops:
        return -1

    visited = set()
    queue = deque()

    # Initialize BFS with all routes containing source
    for bus in bus_stops[source]:
        queue.append((bus, 1))
        visited.add(bus)

    while queue:
        curr_bus, num_changes = queue.popleft()

        # Check if any stop in current route is the target
        for stop in routes[curr_bus]:
            if stop == target:
                return num_changes

            # Add connected routes to queue
            for connected_bus in bus_stops[stop]:
                if connected_bus not in visited:
                    queue.append((connected_bus, num_changes + 1))
                    visited.add(connected_bus)

    return -1
